const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sum=a=>a.reduce((s,x)=>s+x,0),fmt=(n,d=0)=>Number(n).toLocaleString('id-ID',{maximumFractionDigits:d,minimumFractionDigits:d}),pct=(n,d=1)=>fmt(n*100,d)+'%',money=n=>'Rp'+(Math.abs(n)>=1e12?fmt(n/1e12,2)+' T':Math.abs(n)>=1e9?fmt(n/1e9,1)+' M':Math.abs(n)>=1e6?fmt(n/1e6,1)+' jt':fmt(n)),tn=n=>money(n*1e12);
const names={current:'Kebijakan saat ini',rules:'Aturan alokasi',software:'Koordinasi digital',targeted:'Peningkatan terarah',large:'Ekspansi fisik'};
const nav=[['MONITOR',[['overview','Ringkasan','grid'],['twin','Digital twin','cube'],['forecast','Proyeksi','chart']]],['PUTUSKAN',[['lab','Policy Lab','flask'],['capacity','Kapasitas & mitra','truck'],['incidents','Insiden & tindakan','alert']]],['EVALUASI',[['impact','Dampak','impact'],['rollout','Tahapan penerapan','flag'],['evidence','Bukti & asumsi','book']]]];
const defaults={page:'twin',policyId:'P_SOFTWARE_70_88',target:.70,buffer:.88,axis:1,capacityMult:1,travelMult:1,discount:.14,inflation:.025,otherDrift:0,scenario:'normal',hour:9.5,speed:1,playing:!matchMedia('(prefers-reduced-motion: reduce)').matches,level:innerWidth<680?'jakarta2d':'region',hub:'H_CAW',layer:'operations',quality:'standard',incidentAction:null,forecastMode:'day',region:'Greater Jakarta'};
let D={},state={...defaults},scene,worker,mc=null,liveHeat=null,rendering=false;
try{const saved=JSON.parse(localStorage.getItem('nexoraops.scenario'));if(saved?.schema_version==='1.0.0')state={...defaults,...sanitise(saved.state),page:'twin',playing:defaults.playing,incidentAction:null}}catch{}
const app=document.querySelector('#app');
function sanitise(x={}){const o={};for(const k of['policyId','scenario','hub','level','layer','quality'])if(typeof x[k]==='string'&&x[k].length<60)o[k]=x[k];for(const[k,l,h]of[['target',.45,.95],['buffer',.7,1],['axis',.8,1.4],['capacityMult',.5,1.2],['travelMult',.7,2],['discount',.05,.3],['inflation',0,.1],['otherDrift',-.5,1],['hour',7,19]])if(Number.isFinite(x[k]))o[k]=Math.max(l,Math.min(h,x[k]));const enums={scenario:['normal','campaign','capacity','corridor','weak','overrun'],hub:['H_CAW','H_TOM','H_DEP','H_BEK_CAND'],level:['region','hub','indonesia','jakarta2d'],layer:['operations','capacity','cost'],quality:['standard','low']};for(const[k,v]of Object.entries(enums))if(k in o&&!v.includes(o[k]))delete o[k];return o}
const toast=text=>{const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3300)};
function policy(){return{...(D.policies?.finalists.find(p=>p.policy_id===state.policyId)||D.policies.finalists.find(p=>p.package==='software')),target:state.target,buffer:state.buffer}}
function options(){return{axis:state.axis,capacityMult:state.capacityMult*(state.scenario==='capacity'?.7:1),travelMult:state.travelMult*(state.scenario==='corridor'?1.6:1),discount:state.discount,otherDrift:state.otherDrift,inflation:state.inflation}}
function world(){const w=central();if(state.scenario==='weak'){w.eff=[0];w.adoption=[.5]}if(state.scenario==='overrun'){w.overrun=[1.6];w.adoption=[.65]}return w}
function calculation(){const o=options();if(state.scenario==='campaign')o.axis*=1.35;return evaluate(world(),policy(),o)}
const sig=()=>JSON.stringify([state.policyId,state.target,state.buffer,state.axis,state.capacityMult,state.travelMult,state.discount,state.otherDrift,state.scenario,state.inflation]);
const baseSettings=()=>state.axis===1&&state.capacityMult===1&&state.travelMult===1&&state.discount===.14&&state.otherDrift===0&&state.inflation===.025&&state.scenario==='normal'&&state.target===D.policies.finalists.find(p=>p.policy_id===state.policyId)?.target&&state.buffer===D.policies.finalists.find(p=>p.policy_id===state.policyId)?.buffer;
function regional(){
 const p=policy(),ref=D.regional.results[state.policyId]||D.regional.results.P_SOFTWARE_70_88;
 if(state.incidentAction){const a=D.incident.actions.find(a=>a.action_id===state.incidentAction),b=D.incident.base_window;const mix=k=>a[k].map((v,i)=>Array.isArray(v)?v.map((n,j)=>n+2*b[k][i][j]):v+2*b[k][i]);const effective=ref.capacity_daily_available.map((v,i)=>i===0?v*(1-D.incident.daily_capacity_loss_fraction):v);return{...ref,capacity_daily_available:effective,capacity_daily_planning:effective.map(v=>v*.88),internal:mix('internal'),external:mix('external'),emergency:mix('emergency'),deferred:mix('deferred'),cost_idr:a.cost_idr+D.incident.other_8h_cost_idr,incident:true,physical_hub_utilisation:mix('internal').map((a,i)=>sum(a)/effective[i]),unused_capacity_daily:mix('internal').map((a,i)=>effective[i]-sum(a)),full_daily_cost_idr:a.cost_idr+D.incident.other_8h_cost_idr+1.2e9,realised_internal_share:sum(mix('internal').flat())/ref.daily_demand}}
 if(state.axis===1&&state.capacityMult===1&&state.travelMult===1&&state.target===ref.target_internal_share_ceiling&&state.buffer===ref.buffer&&state.scenario==='normal')return ref;
 const axis=state.axis*(state.scenario==='campaign'?1.35:1),z=D.zoneList,d=z.map(x=>x.daily_parcels*axis),h=p.package==='large'?4:3,raw=[240000,210000,160000,120000].slice(0,h).map(x=>x*(p.package==='targeted'?1.18:p.package==='large'?1.35:1)*options().capacityMult);let cp=raw.map(x=>x*state.buffer),ceiling=sum(d)*state.target;cp=cp.map(x=>x*Math.min(1,ceiling/sum(cp)));
 const dist=Array.from({length:h},(_,i)=>D.routes.lanes.slice(i*9,i*9+9).map(l=>l.corridor_network_km)),stops=[14,14,12,13,10,11,10,9,11],cost=dist.map(row=>row.map((km,j)=>{let c=2400+35000/stops[j]+1900+.04*3500+(2*km/30*55000*options().travelMult+2*km*900)/180;if(['software','targeted','large'].includes(p.package))c*=.985;return km/30*60*options().travelMult>120?1e6:c}));
 let r;const external=[10000,10000,10000,10000,11000,11000,11000,11000,11000];if(p.package==='current'){r=minCostFlow(d.map(x=>x*.5),cost,raw,external,0);r.external=d.map(x=>x*.5);r.cost_idr+=sum(r.external.map((v,i)=>v*external[i]));cp=raw.slice()}else r=minCostFlow(d,cost,cp,external,sum(d)*.7);
 return{...r,daily_demand:sum(d),capacity_daily_available:raw,capacity_daily_planning:cp,unused_capacity_daily:raw.map((v,i)=>v-sum(r.internal[i])),physical_hub_utilisation:raw.map((v,i)=>sum(r.internal[i])/v),full_daily_cost_idr:r.cost_idr+1.2e9,daily_committed_cost_idr:1.2e9};
}
function metric(label,value,sub,cls=''){return`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value ${cls}">${value}</div><div class="metric-sub">${sub}</div></div>`}
function pageHeading(eye,title,description,actions=''){return`<div class="page-heading"><div><p class="eyebrow">${eye}</p><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
const button=(action,text,ic='arrow',cls='')=>`<button data-action="${action}" class="${cls}">${icon(ic)}${text}</button>`;
function chart(series,{labels=['2026','2027','2028','2029','2030'],min=0,max=null,unit='',height=230,band=false}={}){
 const w=720,h=height,pad={l:48,r:15,t:15,b:36},all=series.flatMap(s=>s.values),lo=Math.min(min,...all),hi=max??Math.max(...all)*1.15,range=hi-lo||1,x=i=>pad.l+i*(w-pad.l-pad.r)/(labels.length-1),y=v=>h-pad.b-(v-lo)/range*(h-pad.t-pad.b);let s=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(series.map(s=>s.name).join(', '))}">`;
 for(let i=0;i<5;i++){const v=lo+range*i/4,yy=y(v);s+=`<line class="grid" x1="${pad.l}" y1="${yy}" x2="${w-pad.r}" y2="${yy}"/><text x="${pad.l-10}" y="${yy+3}" text-anchor="end">${fmt(v,Math.abs(hi)<10?1:0)}</text>`}
 if(band){const vals=series[series.length-1].values,up=vals.map((v,i)=>`${x(i)},${y(v*(1+.03+i*.012))}`),dn=vals.map((v,i)=>`${x(i)},${y(v*(1-.03-i*.012))}`).reverse();s+=`<path d="M${up.join('L')}L${dn.join('L')}Z" fill="#f4d9c8" opacity=".65"/>`}
 series.forEach(s2=>{s+=`<path d="M${s2.values.map((v,i)=>`${x(i)},${y(v)}`).join('L')}" fill="none" stroke="${s2.color||'#c65317'}" stroke-width="2.5" ${s2.dash?'stroke-dasharray="6 6"':''}/>`;s2.values.forEach((v,i)=>{if(labels.length<8)s+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${s2.color||'#c65317'}"/>`})});labels.forEach((l,i)=>s+=`<text x="${x(i)}" y="${h-10}" text-anchor="middle">${esc(l)}</text>`);return s+`<text x="8" y="12">${unit}</text></svg>`;
}
function legend(items){return`<div class="chart-legend">${items.map(([label,c])=>`<span><i class="legend-line" style="background:${c}"></i>${label}</span>`).join('')}</div>`}
function barChart(values){const max=Math.max(...values.map(v=>Math.abs(v.value)),.01);return`<svg class="chart" viewBox="0 0 680 ${values.length*43+20}" role="img" aria-label="Perbandingan NPV"><line x1="240" y1="0" x2="240" y2="${values.length*43}" stroke="#dce3dd"/>${values.map((v,i)=>{const width=Math.abs(v.value)/max*285;return`<text x="0" y="${i*43+24}" style="fill:#55665c;font-size:12px">${esc(v.name)}</text><rect x="${v.value<0?240-width:240}" y="${i*43+8}" width="${width}" height="24" rx="3" fill="${v.value<0?'#d9b7ae':v.selected?'#c65317':'#9fb8ae'}"/><text x="${v.value<0?248:250+width}" y="${i*43+24}" style="fill:#45594e;font-size:11px">${fmt(v.value,2)} T</text>`}).join('')}</svg>`}
function render(){if(!D.config)return;rendering=true;scene?.dispose();scene=null;const c=calculation(),p=policy();
 app.innerHTML=`<div class="app-shell"><div class="mobile-backdrop"></div><aside class="sidebar"><div class="brand"><span class="brand-mark">N</span>Nexora<em>Ops</em></div><nav aria-label="Navigasi utama">${nav.map(([g,items])=>`<div class="nav-group">${g}</div>${items.map(([id,label,ic])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='incidents'?'<span class="badge">1</span>':''}</button>`).join('')}`).join('')}</nav><div class="sidebar-foot"><span class="status-dot"></span>Mesin simulasi lokal<br>Model 1.0 · Data skenario<br><span>Greater Jakarta · Indonesia</span></div></aside><div class="workspace"><header class="topbar"><div class="topbar-left"><button class="menu-button quiet" data-action="menu" aria-label="Buka navigasi">${icon('menu')}</button><div class="location">${icon('pin')}<strong>${state.level==='indonesia'?'Indonesia':'Greater Jakarta'}</strong></div><span class="divider"></span><select class="policy-select" id="top-policy" aria-label="Kebijakan aktif">${D.policies.finalists.map(pp=>`<option value="${pp.policy_id}" ${pp.policy_id===state.policyId?'selected':''}>${names[pp.package]} · batas ${pct(pp.target,0)} / utilisasi ${pct(pp.buffer,0)}</option>`).join('')}</select></div><div class="topbar-right"><span class="prototype">Prototipe · data simulasi</span>${button('tour','Jelajah demo','play','quiet small')}${button('save','Simpan','save','small')}<span class="avatar" title="Operator demo">NO</span></div></header><main id="main" tabindex="-1">${({twin:twinPage,overview:overviewPage,forecast:forecastPage,lab:labPage,capacity:capacityPage,incidents:incidentPage,impact:impactPage,rollout:rolloutPage,evidence:evidencePage}[state.page]||twinPage)(c,p)}<div class="footer-label">NexoraOps · Optimasi jaringan pengiriman</div></main></div></div><input class="file-input" id="import-file" type="file" accept="application/json,.json">`;
 bind();if(state.page==='twin'&&['region','hub'].includes(state.level)){scene=new Scene(document.querySelector('#scene'),{zones:D.zones,facilities:D.facilities,corridors:D.corridors,onSelect:selectHub,quality:state.quality,activity:{daily_demand:regional().daily_demand,ratio:sum(regional().internal.flat())/regional().daily_demand,selectedVolume:sum(regional().internal[['H_CAW','H_TOM','H_DEP','H_BEK_CAND'].indexOf(state.hub)]||[])}});scene.selected=state.hub;scene.setMode(state.level==='hub'?'hub':'region');scene.playing=state.playing;scene.speed=state.speed;scene.t=(state.hour-7)*20;updateSceneLabels()}
 rendering=false;document.title=`${nav.flatMap(x=>x[1]).find(x=>x[0]===state.page)?.[1]} · NexoraOps`;
}
function twinPage(c,p){const r=regional(),daily=sum(r.internal.flat())+sum(r.external)+sum(r.emergency)+sum(r.deferred),inside=sum(r.internal.flat())/daily,cost=(r.cost_idr+1.2e9)/daily;
 return pageHeading('JARINGAN PENGIRIMAN',state.level==='hub'?'Operasi fasilitas':'Jaringan pengiriman','Pantau alokasi, kapasitas, dan arus pengiriman di seluruh jaringan.',button('settings','Atur skenario','settings'))+`<div class="metrics">${metric('Beban regional / hari',fmt(daily), '20% volume nasional · asumsi alokasi')}${metric('Alokasi NexExpress',pct(inside),pct(1-inside)+' mitra / tertunda · regional')}${metric('Biaya regional / parsel',money(cost),'Termasuk biaya tetap asumsi')}${metric('Ruang kapasitas',fmt(Math.max(0,sum(r.capacity_daily_available||[610000])-sum(r.internal.flat()))),'Parsel/hari · fisik tersedia','positive')}</div><div class="scene-panel"><div class="scene-main"><div class="scene-top"><div class="segmented" aria-label="Skala peta">${[['indonesia','Indonesia'],['region','Jakarta'],['hub','Fasilitas']].map(([k,v])=>`<button data-level="${k}" class="${state.level===k||state.level==='jakarta2d'&&k==='region'?'active':''}">${v}</button>`).join('')}</div><div class="filter-controls"><select id="layer" aria-label="Lapisan jaringan"><option value="operations" ${state.layer==='operations'?'selected':''}>Lapisan operasi</option><option value="capacity" ${state.layer==='capacity'?'selected':''}>Kapasitas</option><option value="cost" ${state.layer==='cost'?'selected':''}>Keunggulan biaya</option></select><button class="small quiet" data-action="toggle2d">${state.level==='jakarta2d'?'3D':'2D'}</button></div></div>${state.level==='indonesia'?indonesiaMap():state.level==='jakarta2d'?jakartaMap(r):`<div class="scene-wrap" id="scene"><div class="scene-credit">${state.level==='hub'?'CUTAWAY FASILITAS · GEOMETRI PROSEDURAL':'GREATER JAKARTA · KORIDOR SKEMATIS'}</div><div class="scene-corner"><span class="key"><i class="swatch"></i>NexExpress</span><span class="key"><i class="swatch partner"></i>Mitra</span><span>Gerakan = agregat aktivitas</span></div><div class="scene-tools"><button data-action="zoom-in" aria-label="Perbesar">${icon('plus')}</button><button data-action="zoom-out" aria-label="Perkecil">${icon('minus')}</button><button data-action="camera-reset" aria-label="Atur ulang kamera">${icon('reset')}</button></div></div>`}<div class="playback"><button data-action="play" aria-label="${state.playing?'Jeda':'Putar'} simulasi">${icon(state.playing?'pause':'play')}</button><strong data-clock>${clock()}</strong><input type="range" id="timeline" min="7" max="19" step=".02" value="${state.hour}" aria-label="Waktu simulasi"><select id="speed" aria-label="Kecepatan simulasi">${[1,3,10].map(x=>`<option ${state.speed===x?'selected':''}>${x}×</option>`).join('')}</select></div></div><aside class="inspector" id="inspector">${inspector(r)}</aside></div><p class="quiet-note">${state.level==='indonesia'?'Peta nasional skematis · Ringkasan pasar representatif':'Koridor & fasilitas: asumsi perencanaan tim · Seret untuk orbit · Klik kanan untuk geser · Gulir untuk zoom'}</p><div class="section-line"><h2>Fasilitas dalam skenario</h2><span class="tag">${names[p.package]}</span></div>${facilityTable(r)}`;
}
function clock(){return`${String(Math.floor(state.hour)).padStart(2,'0')}:${String(Math.floor(state.hour%1*60)).padStart(2,'0')} WIB`}
function routeCost(i,j){const l=D.routes.lanes[i*9+j],km=l.corridor_network_km,stops=[14,14,12,13,10,11,10,9,11][j];return(2400+35000/stops+1900+.04*3500+(2*km/30*55000*options().travelMult+2*km*900)/180)*(['software','targeted','large'].includes(policy().package)?.985:1)}
function hubCost(i,r){const q=r.internal[i]||[],v=sum(q);return v?sum(q.map((x,j)=>x*routeCost(i,j)))/v:null}
function updateSceneLabels(){if(!scene||state.level==='hub')return;const r=regional();document.querySelectorAll('.map-label.hub').forEach((b,i)=>{const vol=sum(r.internal[i]||[]),cap=r.capacity_daily_available?.[i]||0,c=hubCost(i,r);b.textContent=['Cawang','Tomang','Depok','Bekasi'][i]+(state.layer==='capacity'?' · '+(cap?pct(vol/cap):'Nonaktif'):state.layer==='cost'?' · '+(c===null?'Nonaktif':money(c)):'')})}
function showRoutes(){const i=['H_CAW','H_TOM','H_DEP','H_BEK_CAND'].indexOf(state.hub),el=document.createElement('div');el.id='route-overlay';el.innerHTML=`<div class="modal-backdrop"></div><section class="modal route-modal" role="dialog" aria-modal="true" aria-label="Rute layanan"><div class="panel-head"><h2>Rute layanan · ${['Cawang','Tomang','Depok','Bekasi'][i]}</h2><button id="close-routes" class="quiet" aria-label="Tutup rute">${icon('close')}</button></div><p>Jarak koridor dan biaya variabel per parsel · asumsi perencanaan tim.</p><div class="table-scroll"><table><thead><tr><th>Zona</th><th class="num">Koridor km</th><th class="num">Menit satu arah</th><th class="num">Biaya/parsel</th></tr></thead><tbody>${D.routes.lanes.slice(i*9,i*9+9).map((l,j)=>`<tr><td>${esc(D.zoneList[j].name)}</td><td class="num">${fmt(l.corridor_network_km,1)}</td><td class="num">${fmt(l.estimated_one_way_minutes*options().travelMult,0)}</td><td class="num">${money(routeCost(i,j))}</td></tr>`).join('')}</tbody></table></div><p class="quiet-note">Biaya mencakup penanganan, produktivitas lokal, dan perjalanan. Biaya tetap harian dihitung pada total regional.</p></section>`;document.body.append(el);el.querySelector('#close-routes').onclick=()=>el.remove();el.querySelector('.modal-backdrop').onclick=()=>el.remove();trap(el.querySelector('.modal'));el.querySelector('#close-routes').focus()}
function inspector(r){const ids=['H_CAW','H_TOM','H_DEP','H_BEK_CAND'],i=ids.indexOf(state.hub),namesh=['Cawang Sorting Hub','Tomang Distribution Hub','Depok Delivery Hub','Bekasi · kandidat'],cap=(r.capacity_daily_available||[240000,210000,160000])[i]||0,vol=r.internal[i]?sum(r.internal[i]):0,util=cap?vol/cap:0;
 if(state.level==='indonesia'){const mi={Medan:2,Surabaya:0,Makassar:3,Balikpapan:2,Jayapura:3}[state.region]??1,op=calculation().op[4],types=['Urban padat','Suburban','Regional','Sulit / antarpulau'];return`<div><p class="eyebrow">PERSPEKTIF NASIONAL</p><h2>${esc(state.region)}</h2><p>${types[mi]} · pemetaan tipe pasar oleh tim.</p></div><div class="stat-lines"><div class="stat-line"><span>Volume nasional</span><strong>2 miliar / tahun</strong></div><div class="stat-line"><span>Internal · tipe pasar</span><strong>${pct(op.q[mi]/op.d[mi])}</strong></div><div class="stat-line"><span>Utilisasi · tipe pasar</span><strong>${pct(op.util[mi])}</strong></div></div><div class="inspector-note">Bobot nasional adalah asumsi. Penghematan Jakarta tidak dikalikan rata ke seluruh Indonesia.</div><div class="inspector-actions">${button('jakarta','Jelajahi Greater Jakarta','arrow','primary')}</div>`;}
 return`<div><p class="eyebrow">${state.level==='hub'?'SIMULASI FASILITAS':'FASILITAS TERPILIH'}</p><h2>${namesh[i]}</h2><span class="tag ${i===3?'warn':''}">${i===3?'Kandidat investasi':'Fasilitas regional'}</span></div><div><div class="stat-line"><span>Utilisasi fisik</span><strong>${pct(util)}</strong></div><div class="capacity-bar"><i style="width:${Math.min(util*100,100)}%"></i></div><p>${fmt(vol)} dari ${fmt(cap)} parsel / hari</p></div><div class="stat-lines">${state.layer==='cost'?`<div class="stat-line"><span>Biaya variabel / parsel</span><strong>${hubCost(i,r)===null?'—':money(hubCost(i,r))}</strong></div>`:''}<div class="stat-line"><span>Ruang tersedia</span><strong>${fmt(Math.max(0,cap-vol))}</strong></div><div class="stat-line"><span>Batas perencanaan</span><strong>${pct(state.buffer,0)}</strong></div><div class="stat-line"><span>Jendela operasi</span><strong>07.00–19.00</strong></div></div><div class="inspector-note">${state.layer==='cost'?'Keunggulan biaya bergantung jarak koridor, penanganan, dan produktivitas asumsi.':'Alokasi dihitung bersama kapasitas hub lain dan reservasi mitra. Visual kendaraan mewakili aktivitas agregat.'}</div><div class="inspector-actions">${button(state.level==='hub'?'jakarta':'facility',state.level==='hub'?'Kembali ke jaringan':'Jelajahi fasilitas','cube','primary')}${button('capacity','Lihat kapasitas','arrow','')}${button('routes','Rute layanan','truck','quiet small')}</div>`;
}
function facilityTable(r){return`<div class="panel table-scroll"><table><thead><tr><th>Fasilitas regional</th><th class="num">Kapasitas fisik / hari</th><th class="num">Terpakai / hari</th><th class="num">Utilisasi</th><th></th></tr></thead><tbody>${D.facilities.features.map((f,i)=>{const cap=r.capacity_daily_available?.[i]??0,vol=r.internal[i]?sum(r.internal[i]):0;return`<tr><td><strong>${['Cawang','Tomang','Depok','Bekasi · kandidat'][i]}</strong><div class="metric-sub">${i===3?'Kapasitas aktif pada paket ekspansi':'Klaster layanan model'}</div></td><td class="num">${fmt(cap)}</td><td class="num">${fmt(vol)}</td><td class="num">${cap?pct(vol/cap):'—'}</td><td><button class="table-button" data-hub="${f.properties.hub_id}">Inspeksi ${icon('chevron')}</button></td></tr>`}).join('')}</tbody></table></div>`}
function jakartaMap(r){return`<div class="map2d"><svg viewBox="0 0 850 520" role="img" aria-label="Peta skematis jaringan Jakarta"><rect width="850" height="520" fill="#edf2ed"/><path d="M0 40Q200 110 400 40T850 40V0H0" fill="#c3dde0"/>${D.corridors.features.map(f=>{const pts=f.geometry.coordinates.map(([x,y])=>`${(x-106.5)/.55*750+40},${(-y-6.09)/.56*425+50}`);return`<path d="M${pts.join('L')}" stroke="#bbc9bd" stroke-width="3" fill="none"/>`}).join('')}${D.facilities.features.map((f,i)=>{const[x,y]=f.geometry.coordinates,xx=(x-106.5)/.55*750+40,yy=(-y-6.09)/.56*425+50;return`<g class="city" data-hub="${f.properties.hub_id}" role="button" tabindex="0" aria-label="Pilih ${f.properties.hub_id}"><circle cx="${xx}" cy="${yy}" r="8"/><text x="${xx+14}" y="${yy+4}">${['Cawang','Tomang','Depok','Bekasi'][i]}</text></g>`}).join('')}</svg></div>`}
function indonesiaMap(){const islands=['M110 130 140 135 168 160 180 190 208 220 230 254 220 275 190 244 163 210 140 193 120 158Z','M228 282 270 283 310 294 348 302 400 308 438 318 430 328 381 326 334 318 290 309 249 299Z','M325 120 365 98 410 117 441 144 430 180 403 212 361 214 335 184Z','M474 164 494 134 508 119 520 131 510 168 536 151 551 153 535 180 515 192 525 225 508 241 491 205 476 215 461 202Z','M624 203 650 186 673 195 695 184 736 195 762 220 791 226 805 257 778 267 747 253 726 237 692 230 663 221 638 226Z'];const cities=[['Medan',158,171],['Jakarta',260,291],['Surabaya',381,315],['Makassar',505,219],['Balikpapan',419,184],['Jayapura',771,223]];return`<div class="map2d"><svg viewBox="0 0 850 520" role="img" aria-label="Indonesia skematis; pilih kota"><text x="40" y="70" style="font-size:11px;letter-spacing:2px">INDONESIA · TIPE PASAR REPRESENTATIF</text>${islands.map(d=>`<path class="island" d="${d}"/>`).join('')}${[455,480,514,550,575].map((x,i)=>`<ellipse class="island" cx="${x}" cy="${327+i*3}" rx="${8+i*2}" ry="4"/>`).join('')}${cities.slice(0).map(([name,x,y])=>`<path class="route-line" d="M260 291Q${x} 220 ${x} ${y}"/>`).join('')}${cities.map(([name,x,y])=>`<g class="city" data-city="${name}" tabindex="0" role="button" aria-label="Pilih ${name}"><circle cx="${x}" cy="${y}" r="${name==='Jakarta'?8:5}"/><text x="${x+11}" y="${y+4}">${name}</text></g>`).join('')}<text x="40" y="464">Ilustrasi pulau · bukan batas administratif resmi</text></svg></div>`}
function overviewPage(c,p){const f=c.financial;return pageHeading('RINGKASAN SKENARIO','Keputusan hari ini. Dampak ke depan.','Lihat kondisi operasional dan konsekuensi keuangan dari kebijakan aktif.',button('settings','Atur skenario','settings'))+`<div class="metrics">${metric('NPV proyek · sentral',tn(f.npv),'5 tahun · diskonto '+pct(state.discount),f.npv>=0?'positive':'negative')}${metric('Porsi internal nasional',pct(c.op[4].share),'Realisasi tahun 5; batas '+pct(state.target,0))}${metric('Biaya nasional · tahun 5',money(c.op[4].cost/c.op[4].d.reduce((a,b)=>a+b,0)*1000),'Nominal IDR / parsel')}${metric('Pertumbuhan laba tahunan',f.growthPass?'Lolos':'Tidak lolos','Diuji setiap tahun mulai tahun 1',f.growthPass?'positive':'negative')}</div>${growthCallout(c)}<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Jalur laba operasional grup</h2><p>Rp triliun · kebijakan dan pembanding dengan beban yang sama</p></div></div><div class="panel-body">${legend([['Kebijakan aktif','#c65317'],['Pembanding','#9faea5']])}${chart([{name:'Pembanding',values:f.rows.map(x=>x.cfprofit),color:'#9faea5'},{name:'Kebijakan',values:f.rows.map(x=>x.profit)}],{unit:'Rp T'})}</div></section><section class="panel"><div class="panel-head"><h2>Fokus keputusan</h2></div><div class="panel-body"><div class="driver"><h3>${icon('flask')}Bandingkan sebelum berinvestasi</h3><p>Aturan alokasi pada TMS yang ada adalah alternatif serius bagi paket software.</p></div><div class="driver"><h3>${icon('truck')}Jaga ruang kapasitas</h3><p>Batas utilisasi ${pct(state.buffer,0)} menyisakan ruang menghadapi lonjakan. Volume overflow tetap memakai mitra.</p></div><div class="driver"><h3>${icon('alert')}Uji gangguan fasilitas</h3><p>Bandingkan pengalihan, reservasi 3PL, dan kapasitas darurat pada jendela 4 jam.</p></div>${button('incidents','Buka skenario insiden','arrow','primary')}</div></section></div>`}
function growthCallout(c){return`<div class="decision-note">${icon(c.financial.growthPass?'check':'alert')}<p><strong>${c.financial.growthPass?'Skenario ini melewati uji pertumbuhan laba.':'Nilai investasi dan pertumbuhan laba grup'}</strong> ${c.financial.growthPass?'Hasil bergantung asumsi kontribusi lain dan kondisi yang dipilih.':'Pada asumsi sentral awal, seluruh 133 kebijakan gagal memenuhi pertumbuhan laba positif di setiap tahun. Buka Dampak untuk melihat penyebabnya.'}</p></div>`}
function forecastPage(c,p){const r=regional(),day=state.forecastMode==='day',labels=day?['07.00','09.00','11.00','13.00','15.00','17.00','19.00']:['Sen','Sel','Rab','Kam','Jum','Sab','Min'],rawShape=day?[.48,.72,1.12,.89,1.02,1.3,.65]:[.96,1,1.03,1.05,1.15,1.21,.92],normalizer=day?(sum(rawShape)-(rawShape[0]+rawShape.at(-1))/2)/6:sum(rawShape)/7,shape=rawShape.map(x=>x/normalizer),base=r.daily_demand/(day?12:1),demand=shape.map(x=>base*x),internalCapacity=sum(r.capacity_daily_available)/(day?12:1),capacity=labels.map(()=>internalCapacity),allocation=demand.map(x=>Math.min(x*state.target,internalCapacity*state.buffer));return pageHeading('PROYEKSI BEBAN & KAPASITAS','Antisipasi sebelum antrean tumbuh.','Antisipasi beban intrahari dan mingguan, lalu sesuaikan alokasi dan kapasitas.',`<div class="segmented"><button data-forecast="day" class="${day?'active':''}">Intrahari</button><button data-forecast="week" class="${!day?'active':''}">7 hari</button></div>`)+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Beban pengiriman regional</h2><p>${day?'Laju per jam di titik waktu':'Total per hari'} · pola relatif yang diasumsikan</p></div><span class="tag warn">Proyeksi skenario</span></div><div class="panel-body">${legend([['Permintaan','#c65317'],['Rentang skenario','#f4d9c8']])}${chart([{name:'Permintaan',values:demand}],{labels,band:true,height:285,unit:'Parsel'})}<p class="quiet-note">Rentang menunjukkan variasi pola dalam asumsi perencanaan tim.</p></div><div class="panel-head"><div><h2>Beban internal dan batas kapasitas</h2><p>Overflow ditawarkan ke mitra; tidak dihilangkan dari total.</p></div></div><div class="panel-body">${legend([['Alokasi internal','#c65317'],['Kapasitas fisik','#9fafa5']])}${chart([{name:'Kapasitas fisik',values:capacity,color:'#9fafa5'},{name:'Alokasi internal',values:allocation}],{labels,height:245,unit:'Parsel'})}</div></section><section class="panel"><div class="panel-head"><h2>Apa yang menggerakkan proyeksi?</h2></div><div class="panel-body"><div class="driver"><h3>Beban dasar regional</h3><div class="driver-value">${fmt(r.daily_demand)} <span class="unit">parsel / hari</span></div><p>Alokasi regional 20% dari volume nasional, disesuaikan pengali beban ${pct(state.axis,0)}.</p></div><div class="driver"><h3>Pola waktu</h3><p>${day?'Profil memiliki puncak sore yang diasumsikan.':'Pola mingguan memakai pengali harian yang diasumsikan.'} Profil waktu dan faktor kampanye menggunakan asumsi perencanaan tim.</p></div><div class="driver"><h3>Skenario aktif</h3><p>${scenarioName()} · faktor perjalanan ${fmt(options().travelMult,2)}× · kapasitas tersedia ${pct(options().capacityMult,0)}.</p></div><div class="driver"><h3>Dari proyeksi ke keputusan</h3><p>Ubah batas alokasi atau tambah kapasitas, lalu bandingkan kembali biaya dan layanan pada Policy Lab.</p></div>${button('lab','Bandingkan kebijakan','arrow','primary')}</div></section></div>`}
function heatCells(){if(liveHeat?.signature===sig())return liveHeat.cells.map(x=>({...x,target_share:x.target,demand_axis:x.axis,expected_npv_tn:x.mean,realised_internal_share:x.share,feasible:x.violation<=.1&&x.share+.005>=x.target}));return D.heatmap.cells}
function labPage(c,p){const s=D.policies.finalists.find(x=>x.policy_id===state.policyId),cells=heatCells(),targets=[.45,.5,.55,.6,.65,.7,.75,.8,.85,.9,.95],axes=[.8,.9,1,1.1,1.2,1.4],activeMC=mc?.signature===sig()?mc:null;return pageHeading('POLICY LAB','Uji kebijakan. Pahami risikonya.','Perbandingan investasi, alokasi, dan layanan pada dunia operasi yang sama.',button('settings','Parameter','settings'))+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Peta keputusan</h2><p>NPV proyek · Rp triliun · ${liveHeat?.signature===sig()?'dihitung di browser, 100 dunia/sel':'hasil analisis software, buffer 88%, 1.000 dunia/sel'}</p></div><button class="small" data-action="run-heat">${icon('reset')}Hitung ulang</button></div><div class="panel-body"><div class="heat-overflow"><div class="heatmap"><div class="axis">Batas<br>internal</div>${axes.map(x=>`<div class="axis">${pct(x,0)}</div>`).join('')}${targets.map(t=>`<div class="axis">${pct(t,0)}</div>${axes.map(a=>{const x=cells.find(x=>Math.abs(x.target_share-t)<.001&&x.demand_axis===a),v=x.expected_npv_tn,bg=v<0?'#f3dfd7':`hsl(145 17% ${95-Math.min(v,2)*12}%)`;return`<button class="heatcell ${Math.abs(state.target-t)<.001&&state.axis===a?'active':''}" style="background:${bg}" data-cell="${t},${a}" aria-label="Batas ${pct(t,0)}, beban ${pct(a,0)}, NPV ${fmt(v,3)} triliun"><span>${v>=0?'+':''}${fmt(v,2)}${x.feasible?'':'*'}</span><small>${pct(x.realised_internal_share,0)} internal</small></button>`}).join('')}`).join('')}</div></div><div class="heatmap-caption"><span>Beban relatif terhadap 2 miliar parsel/tahun</span><span>Negatif <i class="swatch" style="background:#edc7b8"></i> Positif <i class="swatch" style="background:#abc3b3"></i></span></div><p class="quiet-note">* Realisasi internal di bawah plafon yang dipilih, atau risiko layanan melampaui ambang 10% dunia. Hasil setiap sel memakai alokasi ekonomis yang tersedia.</p></div><div class="panel-head"><div><h2>Perbandingan paket</h2><p>14 finalis · 10.000 dunia baru per finalis · distribusi referensi</p></div></div><div class="panel-body">${barChart(['P_CURRENT','P_RULES_70_88','P_SOFTWARE_70_88','P_TARGETED_75_100','P_LARGE_85_100'].map(id=>{const q=D.policies.finalists.find(x=>x.policy_id===id);return{name:names[q.package],value:q.expected_npv_tn,selected:id===state.policyId}}))}</div></section><section class="panel"><div class="panel-head"><div><h2>Kebijakan terpilih</h2><p>${names[p.package]} · buffer ${pct(state.buffer,0)}</p></div></div><div class="panel-body"><div class="driver-value ${c.financial.npv>=0?'positive':'negative'}">${tn(c.financial.npv)}</div><p class="metric-sub">NPV sentral, dari kondisi aktif · bukan rerata Monte Carlo</p><div class="stat-lines" style="margin:24px 0"><div class="stat-line"><span>Batas / realisasi internal</span><strong>${pct(state.target,0)} / ${pct(c.op[4].share)}</strong></div><div class="stat-line"><span>Investasi awal sentral</span><strong>${tn(c.financial.capex)}</strong></div><div class="stat-line"><span>Uji laba tahunan</span><strong class="negative">${c.financial.growthPass?'Lolos':'Gagal'}</strong></div></div><div class="driver"><h3>Uji ketahanan kebijakan</h3><p>Bandingkan kebijakan pada kondisi permintaan, biaya, dan kapasitas yang sama.</p><div class="filter-controls" style="margin:15px 0"><select id="runs" aria-label="Jumlah dunia"><option value="200">200 dunia</option><option value="1000" selected>1.000 dunia</option><option value="10000">10.000 dunia</option></select><button class="primary small" data-action="run-mc">${icon('play')}Jalankan</button><button class="small quiet" data-action="cancel-mc">Batal</button></div><div id="simulation-progress"></div><div id="mc-results">${activeMC?mcResults(activeMC):`<p class="quiet-note">${baseSettings()?`Distribusi referensi: rerata ${tn(s.expected_npv_tn)}, p10 ${tn(s.p10_npv_tn)}. Hitung ulang untuk kondisi aktif.`:'Parameter berubah. Jalankan Monte Carlo untuk distribusi baru.'}</p>`}</div></div>${button('twin','Lihat di jaringan','cube','primary')}${button('export','Ekspor JSON','download','small')}${button('export-csv','Ekspor CSV','download','small')}</div></section></div>`}
function mcResults(m){const s=m.result,values=s.values,min=Math.min(...values),max=Math.max(...values),bins=Array(24).fill(0);values.forEach(x=>bins[Math.min(23,Math.floor((x-min)/(max-min||1)*24))]++);return`<div class="stat-lines"><div class="stat-line"><span>Rerata NPV</span><strong>${tn(s.mean)}</strong></div><div class="stat-line"><span>p10 / p90</span><strong>${tn(s.p10)} / ${tn(s.p90)}</strong></div><div class="stat-line"><span>NPV positif</span><strong>${pct(s.positive)}</strong></div><div class="stat-line"><span>Dunia melanggar layanan</span><strong>${pct(s.violations)}</strong></div></div><svg class="chart" viewBox="0 0 300 105" role="img" aria-label="Distribusi NPV">${bins.map((n,i)=>`<rect x="${i*12+6}" y="${90-n/Math.max(...bins)*70}" width="9" height="${n/Math.max(...bins)*70}" rx="1" fill="#c65317" opacity=".65"/>`).join('')}<text x="6" y="104">${fmt(min,2)} T</text><text x="245" y="104">${fmt(max,2)} T</text></svg><p class="quiet-note">${fmt(s.n)} dunia · ${fmt(m.runtime/1000,2)} detik di perangkat ini. Persentil adalah hasil distribusi asumsi.</p>`}
function capacityPage(c,p){const r=regional();return pageHeading('KAPASITAS & MITRA','Gunakan ruang yang sudah ada.','Kapasitas fisik, batas perencanaan, dan reservasi mitra dalam satu skenario.',button('settings','Ubah paket','settings'))+facilityTable(r)+`<div class="two-col equal"><section class="panel"><div class="panel-head"><h2>Kapasitas nasional · tahun 5</h2></div><div class="panel-body">${['Urban padat','Suburban','Regional','Sulit / antarpulau'].map((name,i)=>{const op=c.op[4];return`<div class="driver"><div class="stat-line"><span>${name}</span><strong>${pct(op.util[i])}</strong></div><div class="capacity-bar"><i style="width:${op.util[i]*100}%"></i></div><p>${fmt(op.q[i]*1e9)} internal / ${fmt(op.k[i]*1e9)} kapasitas tahunan. Sisa ${fmt(op.unused[i]*1e9)}.</p></div>`}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Komitmen dan batas operasional</h2></div><div class="panel-body"><div class="driver"><h3>Kapasitas bukan sekadar gedung</h3><p>Model memakai batas minimum sortasi, linehaul, dan tenaga pengiriman. Tambahan kapasitas mengasumsikan ketiganya tersedia.</p></div><div class="driver"><h3>Mitra adalah penyangga</h3><p>Volume internal tidak dipaksakan ketika kapasitas atau biaya marginal tidak mendukung. Kapasitas 3PL tetap terbatas.</p></div><div class="driver"><h3>Biaya tetap masih berjalan</h3><p>Memindahkan parsel tidak otomatis menghapus biaya jaringan yang sudah berkomitmen.</p></div>${button('lab','Uji paket investasi','flask','primary')}</div></section></div>`}
function incidentPage(c,p){const inc=D.incident,b=inc.base_window;return pageHeading('INSIDEN & TINDAKAN','Saat jaringan perlu beradaptasi.','Satu gangguan, tiga respons yang dapat dibandingkan. Perhitungan jendela terpisah dari total harian.',button('undo','Batalkan tindakan','reset'))+`<div class="decision-note">${icon('alert')}<p><strong>Cawang: kapasitas turun 50% selama 4 jam.</strong> Pada hari operasi 12 jam, dampak kapasitas harian setara 16,67%. Insiden ini memakai kebijakan aturan alokasi, bukan otomatis mengubah arus kas investasi tahunan.</p></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Bandingkan respons</h2><p>Biaya dan alokasi dalam jendela 4 jam</p></div><span class="tag warn">Gangguan fasilitas</span></div><div class="panel-body">${inc.actions.map((a,i)=>`<div class="policy-option ${state.incidentAction===a.action_id?'selected':''}"><h3>${['Pertahankan rute, tunda volume terdampak','Alokasi ulang hub & reservasi mitra','Tambahkan kapasitas 3PL darurat'][i]}</h3><p>${['Volume yang kehilangan kapasitas dicatat sebagai backlog.','Alokasi dihitung ulang dengan kapasitas hub dan 3PL bersama.','Sediakan hingga 40.000 parsel darurat dengan Rp14.000/parsel.'][i]}</p><div class="action-cost">${money(a.cost_idr)}</div><div class="stat-line"><span>Selisih terhadap jendela normal</span><strong>${money(a.cost_idr-b.cost_idr)}</strong></div><div class="stat-line" style="margin:12px 0"><span>Parsel tertunda</span><strong>${fmt(sum(a.deferred))}</strong></div><button class="small ${state.incidentAction===a.action_id?'':'primary'}" data-incident="${a.action_id}">${state.incidentAction===a.action_id?'Sedang diterapkan':'Terapkan respons'} ${icon('arrow')}</button></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Penilaian insiden</h2></div><div class="panel-body"><div class="driver"><h3>1. Kenali batas</h3><p>Gangguan berlaku pada kapasitas Cawang di jendela 4 jam. Delapan jam lainnya memakai rencana dasar.</p></div><div class="driver"><h3>2. Jaga konservasi volume</h3><p>Internal + eksternal + darurat + backlog harus sama dengan permintaan. Pengiriman yang tertunda tidak dihitung selesai.</p></div><div class="driver"><h3>3. Terapkan satu keputusan</h3><p>Respons diterapkan pada rencana alokasi Greater Jakarta dengan plafon internal 70% dan batas utilisasi 88%.</p></div><div class="driver"><h3>Dampak biaya harian</h3><div class="driver-value">${money(inc.other_8h_cost_idr+(state.incidentAction?inc.actions.find(x=>x.action_id===state.incidentAction).cost_idr:b.cost_idr)+1.2e9)}</div><p>8 jam normal + 4 jam terpilih + biaya tetap harian sekali. Tidak ada asumsi backlog otomatis selesai di hari yang sama.</p></div>${button('twin','Lihat konsekuensi di twin','cube','primary')}</div></section></div>`}
function impactPage(c,p){const f=c.financial;return pageHeading('DAMPAK KEUANGAN & LAYANAN','Pisahkan nilai proyek dan laba grup.','Arus kas investasi dan perubahan laba operasional adalah dua pengujian yang berbeda.',button('print','Cetak ringkasan','print'))+`<div class="metrics">${metric('NPV sentral',tn(f.npv),'5 tahun · nominal IDR',f.npv>=0?'positive':'negative')}${metric('IRR proyek',f.irr===null?'N/A':pct(f.irr),'Tanpa pembiayaan / leverage')}${metric('Payback',f.payback===null?'Tidak tercapai':fmt(f.payback,2)+' th','Diskonto: '+(f.discountedPayback===null?'Tidak tercapai':fmt(f.discountedPayback,2)+' th'))}${metric('Pendanaan puncak',tn(f.peakFunding),'Termasuk modal kerja')}</div>${growthCallout(c)}<section class="panel"><div class="panel-head"><div><h2>Dari penghematan menuju laba grup</h2><p>Rp triliun · permintaan dan monetisasi sama pada setiap pembanding</p></div><span class="tag ${f.growthPass?'':'fail'}">${f.growthPass?'Lolos tahunan':'Gagal uji tahunan'}</span></div><div class="panel-body">${legend([['Kebijakan','#c65317'],['Pembanding','#a6b4aa']])}${chart([{name:'Pembanding',values:f.rows.map(x=>x.cfprofit),color:'#a6b4aa'},{name:'Kebijakan',values:f.rows.map(x=>x.profit)}],{unit:'Rp T',height:275})}</div><div class="table-scroll"><table><thead><tr><th>Tahun</th><th class="num">Penghematan operasi</th><th class="num">Δ EBIT proyek</th><th class="num">Laba grup</th><th class="num">Pertumbuhan YoY</th><th>Uji</th></tr></thead><tbody>${f.rows.map(x=>`<tr><td>${2025+x.year}</td><td class="num">${tn(x.benefit)}</td><td class="num">${tn(x.ebit)}</td><td class="num"><strong>${tn(x.profit)}</strong></td><td class="num ${x.growth>0?'positive':'negative'}">${pct(x.growthRate)}</td><td><span class="tag ${x.growth>0?'':'fail'}">${x.growth>0?'Lolos':'Gagal'}</span></td></tr>`).join('')}</tbody></table></div></section><div class="two-col equal"><section class="panel"><div class="panel-head"><h2>Arus kas proyek</h2></div><div class="panel-body">${chart([{name:'Arus kas',values:f.flows}],{labels:['Awal','Th 1','Th 2','Th 3','Th 4','Th 5'],min:Math.min(...f.flows),unit:'Rp T'})}<p class="quiet-note">Cash flow setelah pajak, transisi, belanja pengganti, modal kerja, dan salvage. Biaya pemeliharaan sudah dihitung pada operasi.</p></div></section><section class="panel"><div class="panel-head"><h2>Asumsi yang dapat diuji</h2></div><div class="panel-body"><label class="field"><span>Diskonto nominal IDR <b>${pct(state.discount)}</b></span><input data-control="discount" type="range" min=".11" max=".18" step=".01" value="${state.discount}"></label><label class="field"><span>Kontribusi lain · Rp miliar / tahun</span><input id="other-drift" type="number" min="-500" max="1000" step="50" value="${state.otherDrift*1000}"><small>Asumsi kenaikan tahunan di luar logistik. Ambang sentral: lebih dari Rp531,4 miliar/tahun.</small></label><label class="field"><span>Inflasi biaya logistik <b>${pct(state.inflation)}</b></span><input data-control="inflation" type="range" min="0" max=".06" step=".005" value="${state.inflation}"></label></div></section></div>`}
function rolloutPage(c,p){return pageHeading('TAHAPAN PENERAPAN','Bertahap, dengan syarat yang jelas.','Empat tahap penerapan dengan keputusan investasi yang terukur.',button('export','Ekspor skenario','download'))+growthCallout(c)+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Urutan keputusan</h2></div><div class="panel-body">${[['Pemetaan operasi','Satukan biaya marginal, kapasitas hub, armada, akses koridor, dan reservasi 3PL ke dalam profil operasi.'],['Konfigurasi alokasi','Bandingkan aturan alokasi dengan praktik saat ini pada lokasi terpilih. Ukur biaya, overflow, dan layanan.'],['Koordinasi digital','Bandingkan manfaat tambahan koordinasi digital terhadap aturan alokasi pada sistem yang ada.'],['Ekspansi selektif','Pilih lokasi berdasarkan kepadatan, biaya rute, layanan, dan utilisasi. Jangan mengasumsikan ekspansi nasional selalu bernilai.']].map(([h,t],i)=>`<div class="step"><span class="step-no">${i+1}</span><div><h3>${h}</h3><p>${t}</p></div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Gerbang keputusan</h2></div><div class="panel-body"><div class="driver"><h3>Nilai investasi</h3><span class="tag ${c.financial.npv>0?'':'fail'}">NPV ${c.financial.npv>0?'positif':'tidak positif'}</span><p>Bandingkan pada horizon dan tingkat diskonto yang sama.</p></div><div class="driver"><h3>Pertumbuhan laba grup</h3><span class="tag ${c.financial.growthPass?'':'fail'}">${c.financial.growthPass?'Lolos dengan asumsi aktif':'Tidak lolos'}</span><p>Harus positif di setiap tahun, termasuk tahun pertama.</p></div><div class="driver"><h3>Cakupan operasi</h3><span class="tag">Greater Jakarta</span><p>Profil fasilitas dan koridor menggunakan asumsi perencanaan tim. Perluasan dilakukan per klaster jaringan.</p></div><div class="driver"><h3>Keputusan</h3><p>Urutkan investasi menurut nilai tambahan, ketahanan layanan, dan kontribusi terhadap laba grup.</p></div></div></section></div>`}
function evidencePage(c,p){return pageHeading('BUKTI & ASUMSI','Angka yang bisa ditelusuri.','Bedakan fakta kasus, hasil perhitungan, observasi eksternal, dan asumsi model.',button('import','Impor skenario','upload'))+`<section class="panel"><div class="panel-head"><h2>Batas model</h2></div><div class="panel-body text-body"><div class="evidence-row"><h3>Fakta kasus</h3><p>2 miliar parsel/tahun; 50% NexExpress; biaya internal Rp8.000 dan eksternal Rp12.000; laba operasi 2025 Rp5 triliun. Sumber: IBSC 2026 Preliminary Casebook.</p></div><div class="evidence-row"><h3>Turunan aritmetika</h3><p>Belanja pengiriman tersirat Rp20 triliun. Rasio GMV/parsel Rp300.000. Residual akuntansi Rp11 triliun tidak dialokasikan sebagai biaya tetap.</p></div><div class="evidence-row"><h3>Simulasi yang dijalankan</h3><p>133 kebijakan × 1.000 dunia screening; 14 finalis × 10.000 dunia baru; 66 sel heatmap × 1.000 dunia. Seed holdout 20261101. Perhitungan browser menggunakan draws ekspor yang sama.</p></div><div class="evidence-row"><h3>Geografi parsial</h3><p>16 titik, 17 koridor, 9 zona, 4 fasilitas asumsi tim. Koridor memakai bobot jarak jaringan; peta dan bangunan memakai geometri skematis prosedural.</p></div><div class="evidence-row"><h3>Interpretasi</h3><p>Persentil Monte Carlo menggambarkan distribusi asumsi biaya, permintaan, dan kapasitas. Proyeksi waktu menggunakan profil perencanaan tim; hasil tidak mengukur retensi atau efek kausal.</p></div></div></section><section class="panel"><div class="panel-head"><h2>Asumsi penting</h2><button class="small" data-action="download-assumptions">${icon('download')}JSON</button></div><div class="table-scroll"><table><thead><tr><th>Asumsi</th><th>Nilai / kisaran</th><th>Makna</th></tr></thead><tbody>${D.assumptions.assumptions.filter(a=>['A01','A05','A10','A14','A26','A27','A29','A37','A40'].includes(a.id)).map(a=>`<tr><td><strong>${esc(a.name)}</strong><div class="metric-sub">Asumsi perencanaan tim</div></td><td>${esc(Array.isArray(a.value)?a.value.join(' / '):a.value)} ${esc(a.unit)}</td><td style="max-width:460px;font-size:11px;line-height:1.7">${esc(a.reason)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Referensi</h2></div><div class="panel-body text-body">${D.sources.sources.map(s=>`<div class="evidence-row"><p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`:esc(s.title)}</p></div>`).join('')}</div></section>`}
function scenarioName(){return{normal:'Normal',campaign:'Lonjakan kampanye',capacity:'Kapasitas turun 30%',corridor:'Gangguan perjalanan',weak:'Produktivitas lemah',overrun:'Implementasi membengkak'}[state.scenario]||'Normal'}
function selectPolicy(id){const p=D.policies.finalists.find(x=>x.policy_id===id);if(!p)return;state.policyId=id;state.target=p.target;state.buffer=p.buffer;state.incidentAction=null;render()}
function selectHub(id){state.hub=id;if(state.page!=='twin'){state.page='twin';state.level='region';render()}else{if(scene){scene.parcelCount=Math.max(0,Math.min(24,Math.round(sum(regional().internal[['H_CAW','H_TOM','H_DEP','H_BEK_CAND'].indexOf(id)]||[])/15000)));scene.setSelected(id)};const el=document.querySelector('#inspector');if(el)el.innerHTML=inspector(regional());bindActions(el)}}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;closeDrawer();render();window.scrollTo(0,0)});bindActions(document);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{state.level=b.dataset.level;render()});document.querySelectorAll('[data-hub]').forEach(b=>{b.onclick=()=>selectHub(b.dataset.hub);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectHub(b.dataset.hub)}}});document.querySelectorAll('[data-city]').forEach(b=>{b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}};b.onclick=()=>{state.region=b.dataset.city;if(b.dataset.city==='Jakarta'){state.level='region';render()}else{document.querySelector('#inspector').innerHTML=inspector(regional());bindActions(document.querySelector('#inspector'));toast('Ringkasan '+state.region+' memakai tipe pasar, bukan volume kota terukur.')}}});
 document.querySelector('#top-policy')?.addEventListener('change',e=>selectPolicy(e.target.value));document.querySelector('#layer')?.addEventListener('change',e=>{state.layer=e.target.value;const r=regional();document.querySelector('#inspector').innerHTML=inspector(r);bindActions(document.querySelector('#inspector'));updateSceneLabels()});
 document.querySelector('#timeline')?.addEventListener('input',e=>{state.hour=+e.target.value;updateClock();if(scene)scene.t=(state.hour-7)*20;updateSceneLabels()});document.querySelector('#speed')?.addEventListener('change',e=>{state.speed=parseInt(e.target.value);if(scene)scene.speed=state.speed});document.querySelectorAll('[data-forecast]').forEach(b=>b.onclick=()=>{state.forecastMode=b.dataset.forecast;render()});document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{const[t,a]=b.dataset.cell.split(',').map(Number);state.target=t;state.axis=a;state.incidentAction=null;render()});document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>{state.policyId=D.incident.base_policy_id;state.target=.7;state.buffer=.88;state.axis=1;state.capacityMult=1;state.travelMult=1;state.scenario='normal';state.incidentAction=b.dataset.incident;render();toast('Respons diterapkan ke skenario regional yang sama.')});
 document.querySelectorAll('[data-control]').forEach(el=>el.onchange=e=>{state[el.dataset.control]=+e.target.value;state.incidentAction=null;render()});document.querySelector('#other-drift')?.addEventListener('change',e=>{state.otherDrift=Math.max(-.5,Math.min(1,+e.target.value/1000));render()});document.querySelector('#import-file')?.addEventListener('change',importScenario);document.querySelector('.mobile-backdrop')?.addEventListener('click',()=>{document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-backdrop').classList.remove('show')});}
function bindActions(root){root?.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action))}
function action(a){if(a==='menu'){document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.mobile-backdrop').classList.toggle('show')}else if(a==='settings')openDrawer();else if(a==='routes')showRoutes();else if(a==='save'){try{localStorage.setItem('nexoraops.scenario',JSON.stringify({schema_version:'1.0.0',state:sanitise(state)}));toast('Skenario tersimpan di perangkat ini.')}catch{toast('Penyimpanan perangkat tidak tersedia; gunakan ekspor JSON.')}}else if(a==='export')download('NexoraOps_Skenario.json',{schema_version:'1.0.0',exported_at:new Date().toISOString(),state:sanitise(state),policy:policy(),results:calculation(),regional_results:regional(),regional_scope:'regional_daily',monte_carlo:mc?.signature===sig()?{...mc,result:{...mc.result,values:undefined}}:null,scope:'national_annual',status:'authored_simulation'});else if(a==='export-csv')exportCSV();else if(a==='import')document.querySelector('#import-file').click();else if(a==='download-assumptions')download('NexoraOps_Asumsi.json',D.assumptions);else if(a==='print')window.print();else if(a==='tour')tour(0);else if(a==='play'){state.playing=!state.playing;if(scene)scene.playing=state.playing;const b=document.querySelector('[data-action=play]');if(b){b.innerHTML=icon(state.playing?'pause':'play');b.setAttribute('aria-label',state.playing?'Jeda simulasi':'Putar simulasi')}}else if(a==='zoom-in'){if(scene){scene.zoom=Math.min(3.5,scene.zoom*1.2);scene.draw()}}else if(a==='zoom-out'){if(scene){scene.zoom=Math.max(.5,scene.zoom/1.2);scene.draw()}}else if(a==='camera-reset')scene?.reset();else if(a==='facility'){state.level='hub';render()}else if(a==='jakarta'){state.page='twin';state.level='region';state.region='Greater Jakarta';render()}else if(a==='toggle2d'){state.level=state.level==='jakarta2d'?'region':'jakarta2d';render()}else if(['capacity','lab','incidents','twin'].includes(a)){state.page=a;render();window.scrollTo(0,0)}else if(a==='undo'){state.incidentAction=null;render();toast('Respons dibatalkan; kembali ke rencana dasar.')}else if(a==='run-mc')runMC(false);else if(a==='run-heat')runMC(true);else if(a==='cancel-mc'){worker?.terminate();worker=null;const el=document.querySelector('#simulation-progress');if(el)el.innerHTML='';toast('Perhitungan dibatalkan.')}}
function updateClock(){document.querySelectorAll('[data-clock]').forEach(el=>el.textContent=clock());const t=document.querySelector('#timeline');if(t)t.value=state.hour}
setInterval(()=>{if(state.playing&&!rendering&&D.config){state.hour+=state.speed*.0025;if(state.hour>19)state.hour=7;updateClock()}},500);
function openDrawer(){closeDrawer();const node=document.createElement('div');node.id='settings-overlay';node.innerHTML=`<div class="drawer-backdrop"></div><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="settings-title"><div class="drawer-head"><h2 id="settings-title">Atur skenario</h2><button id="close-settings" class="quiet" aria-label="Tutup parameter">${icon('close')}</button></div><p class="quiet-note">Parameter mengubah perhitungan nasional dan alokasi regional. Distribusi Monte Carlo perlu dijalankan ulang.</p><label class="field"><span>Paket kebijakan</span><select id="drawer-policy">${D.policies.finalists.filter((p,i,a)=>a.findIndex(x=>x.package===p.package)===i||p.policy_id===state.policyId).map(p=>`<option value="${p.policy_id}" ${p.policy_id===state.policyId?'selected':''}>${names[p.package]} · batas ${pct(p.target,0)} / utilisasi ${pct(p.buffer,0)}</option>`).join('')}</select></label><label class="field"><span>Kondisi operasi</span><select id="drawer-scenario">${['normal','campaign','capacity','corridor','weak','overrun'].map(s=>`<option value="${s}" ${state.scenario===s?'selected':''}>${{normal:'Normal',campaign:'Lonjakan kampanye',capacity:'Kapasitas turun 30%',corridor:'Perjalanan 60% lebih lambat',weak:'Produktivitas lemah',overrun:'Biaya implementasi +60%'}[s]}</option>`).join('')}</select></label>${[['target','Batas maksimum internal',.45,.95,.05],['buffer','Batas utilisasi rencana',.88,1,.06],['axis','Beban parsel relatif',.8,1.4,.05],['capacityMult','Kapasitas tersedia',.7,1.1,.05]].map(([key,l,min,max,step])=>`<label class="field"><span>${l}<b id="label-${key}">${pct(state[key],0)}</b></span><input id="set-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${state[key]}">${key==='target'?'<small>Batas keputusan, bukan target yang harus dipaksakan.</small>':''}</label>`).join('')}<div class="drawer-section"><label class="field"><span>Kualitas tampilan 3D</span><select id="set-quality"><option value="standard">Standar</option><option value="low" ${state.quality==='low'?'selected':''}>Ringan</option></select><small>Hanya mengubah jumlah bangunan dekoratif, bukan volume atau hasil analisis.</small></label></div><button class="primary" id="apply-settings">Terapkan skenario ${icon('arrow')}</button><button class="quiet" id="reset-settings" style="width:100%;margin-top:10px">Kembali ke asumsi sentral</button></section>`;document.body.append(node);const oldFocus=document.activeElement;node._oldFocus=oldFocus;node.querySelector('#close-settings').onclick=closeDrawer;node.querySelector('.drawer-backdrop').onclick=closeDrawer;node.querySelector('#drawer-policy').onchange=e=>{const p=D.policies.finalists.find(x=>x.policy_id===e.target.value);node.querySelector('#set-target').value=p.target;node.querySelector('#set-buffer').value=p.buffer;for(const k of['target','buffer'])node.querySelector('#label-'+k).textContent=pct(p[k],0)};node.querySelectorAll('input[type=range]').forEach(el=>el.oninput=()=>node.querySelector('#label-'+el.id.slice(4)).textContent=pct(+el.value,0));node.querySelector('#apply-settings').onclick=()=>{state.policyId=node.querySelector('#drawer-policy').value;state.scenario=node.querySelector('#drawer-scenario').value;for(const k of['target','buffer','axis','capacityMult'])state[k]=+node.querySelector('#set-'+k).value;state.quality=node.querySelector('#set-quality').value;state.incidentAction=null;closeDrawer();render();toast('Parameter diterapkan ke seluruh tampilan.')};node.querySelector('#reset-settings').onclick=()=>{const page=state.page;state={...defaults,page};closeDrawer();render()};trap(node.querySelector('.drawer'));node.querySelector('#close-settings').focus()}
function closeDrawer(){const node=document.querySelector('#settings-overlay');if(node){node._oldFocus?.focus();node.remove()}}
function trap(el){el.onkeydown=e=>{if(e.key==='Escape'){el.closest('#settings-overlay')?closeDrawer():el.parentNode.remove();return}if(e.key==='Tab'){const list=[...el.querySelectorAll('button,input,select,a[href]')].filter(x=>!x.disabled),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}}
function tour(i){document.querySelector('#tour-overlay')?.remove();const steps=[['twin','Mulai dari jaringan','Lihat alokasi dan kapasitas regional. Pilih sebuah hub, lalu masuk ke fasilitas untuk melihat aktivitas agregat.'],['forecast','Antisipasi beban','Bandingkan profil beban intrahari dan mingguan dengan kapasitas jaringan.'],['lab','Uji sebelum menerapkan','Bandingkan kebijakan pada dunia yang sama. Jalankan Monte Carlo di browser, lalu lihat downside dan layanan.'],['incidents','Hadapi gangguan','Pilih satu respons untuk penurunan kapasitas Cawang. Semua parsel dan biaya jendela harus tetap konsisten.'],['impact','Tinjau gerbang investasi','Nilai proyek positif belum cukup: pertumbuhan laba grup harus positif di setiap tahun. Skenario sentral tidak lolos uji pertumbuhan laba tahunan.']];if(i>=steps.length)return;state.page=steps[i][0];render();const el=document.createElement('div');el.id='tour-overlay';el.innerHTML=`<div class="modal-backdrop"></div><section class="modal" role="dialog" aria-modal="true" aria-label="Jelajah demo"><p class="eyebrow">JELAJAH NEXORAOPS</p><h2>${steps[i][1]}</h2><p>${steps[i][2]}</p><div class="modal-footer"><button id="tour-close" class="quiet">Tutup demo</button><span class="tour-count">${i+1} / ${steps.length}</span><button id="tour-next" class="primary">${i===steps.length-1?'Selesai':'Lanjut'} ${icon('arrow')}</button></div></section>`;document.body.append(el);el.querySelector('#tour-close').onclick=()=>el.remove();el.querySelector('#tour-next').onclick=()=>{el.remove();tour(i+1)};trap(el.querySelector('.modal'));el.querySelector('#tour-next').focus()}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Ekspor disiapkan.')}
async function importScenario(e){try{const file=e.target.files[0];if(!file)return;if(file.size>1e6)throw Error('File terlalu besar');const x=JSON.parse(await file.text());if(x.schema_version!=='1.0.0'||!x.state)throw Error('Versi skenario tidak didukung');const s=sanitise(x.state);if('policyId' in s&&!D.policies.finalists.some(p=>p.policy_id===s.policyId))throw Error('Kebijakan tidak dikenal');state={...state,...s,incidentAction:null};render();toast('Skenario diimpor.')}catch(err){toast('Impor gagal: '+err.message)}}
function runMC(heat){worker?.terminate();worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});const signature=sig(),n=+(document.querySelector('#runs')?.value||1000),start=performance.now(),progress=document.querySelector('#simulation-progress');if(progress)progress.innerHTML='<p class="quiet-note">Menghitung di browser…</p><div class="progress-track"><i style="width:1%"></i></div>';toast(heat?'Menghitung 66 sel, 100 dunia per sel…':'Menjalankan '+fmt(n)+' dunia…');const opts={...options(),scenario:state.scenario,inflation:state.inflation===.025?null:state.inflation};if(state.scenario==='campaign')opts.axis*=1.35;
 worker.onmessage=({data:m})=>{if(m.type==='progress'){const bar=document.querySelector('.progress-track i');if(bar)bar.style.width=m.progress*100+'%'}else if(m.type==='result'){mc={signature,result:m.result,runtime:m.runtime};if(signature===sig()){const el=document.querySelector('#mc-results');if(el)el.innerHTML=mcResults(mc);if(progress)progress.innerHTML=''}toast('Selesai: '+fmt(m.result.n)+' dunia dalam '+fmt(m.runtime/1000,2)+' detik.')}else if(m.type==='heatmap'){liveHeat={signature,cells:m.cells};if(signature===sig())render();toast('Heatmap selesai · '+fmt(m.runtime/1000,2)+' detik.')}else if(m.type==='error'){if(progress)progress.textContent=m.message;toast('Perhitungan gagal: '+m.message)}};
 worker.postMessage({type:heat?'heatmap':'mc',n,policy:policy(),opts});}
async function init(){try{const files={config:'config.json',policies:'policies.json',heatmap:'heatmap.json',regional:'regional_outcomes.json',routes:'routes.json',zones:'decision_zones.geojson',facilities:'facilities.geojson',corridors:'corridors.geojson',incident:'incidents.json',assumptions:'assumptions.json',sources:'sources.json'};await Promise.all(Object.entries(files).map(async([k,f])=>{const r=await fetch('./data/'+f);if(!r.ok)throw Error(f);D[k]=await r.json()}));D.zoneList=D.zones.features.filter(f=>f.properties.policy_id==='P_RULES_70_88').map(f=>f.properties);if(!D.policies.finalists.some(x=>x.policy_id===state.policyId))state={...defaults};render();window.NexoraOps={version:'1.0.0',getState:()=>({...state}),evaluate,central,regional:()=>regional(),getScene:()=>scene?{mode:scene.mode,webgl:!scene.fallback,instances:scene.instances.length/10,fps:scene.fps}:null};}catch(e){app.innerHTML=`<div class="boot"><h1>Data belum dapat dimuat.</h1><p>Jalankan melalui server HTTP atau Vercel. Membuka index.html langsung sebagai file tidak didukung.</p><button onclick="location.reload()">Coba lagi</button><p>${esc(e.message)}</p></div>`}}
init();

function exportCSV(){const c=calculation(),rows=[['year','scope','policy_id','target_ceiling','planning_buffer','demand_bn','internal_bn','external_bn','deferred_bn','cost_idr_tn','project_cashflow_idr_tn','group_op_idr_tn','group_op_yoy_idr_tn']];c.op.forEach((o,i)=>rows.push([2026+i,'national_annual',state.policyId,state.target,state.buffer,sum(o.d),sum(o.q),sum(o.e),sum(o.u),o.cost,c.financial.rows[i].flow,c.financial.rows[i].profit,c.financial.rows[i].growth]));const csv=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='NexoraOps_Hasil_Tahunan.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
